def compressir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        cnt = 1
        i += 1
        while i < n and texto[i] == ch:
            cnt += 1
            i += 1
        result.append(f"{ch}{cnt}")
    return "".join(result)

def iniciales(nombre: str) -> str:
    name = nombre.strip()
    if not name:
        return ""
    words = name.split()
    return ''.join(word[0].upper() for word in words)

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def evaluar(expresion: str) -> int:
    if '/' in expresion or '**' in expresion:
        raise ValueError("Operator not allowed")
    try:
        result = eval(expresion)
    except ZeroDivisionError:
        raise
    except Exception as e:
        raise ValueError(f"Invalid expression: {expresion}")
    return result
